import{_ as t,o as e,c as s,ag as i}from"./chunks/framework.VvOSaRrC.js";const f=JSON.parse('{"title":"POC-First Development Workflow","description":"","frontmatter":{},"headers":[],"relativePath":"en/poc-first.md","filePath":"en/poc-first.md"}'),n={name:"en/poc-first.md"};function o(r,a,l,h,p,d){return e(),s("div",null,[...a[0]||(a[0]=[i(`<h1 id="poc-first-development-workflow" tabindex="-1">POC-First Development Workflow <a class="header-anchor" href="#poc-first-development-workflow" aria-label="Permalink to &quot;POC-First Development Workflow&quot;">​</a></h1><blockquote><p>A phase-based development approach for greenfield features in KRoot-ADK.</p></blockquote><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>POC-First is a structured workflow for building new features from scratch. Instead of writing tests first (TDD) or analyzing existing behavior (DDD), you get it working first, then systematically improve.</p><h3 id="when-to-use" tabindex="-1">When to Use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to Use&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Scenario</th><th>Workflow</th><th>Why</th></tr></thead><tbody><tr><td>Brand new feature</td><td><strong>POC-First</strong></td><td>No behavior to preserve</td></tr><tr><td>New API endpoint</td><td><strong>POC-First</strong></td><td>Greenfield implementation</td></tr><tr><td>New UI component</td><td><strong>POC-First</strong></td><td>Build first, test after</td></tr><tr><td>Refactoring existing code</td><td>DDD</td><td>Must preserve behavior</td></tr><tr><td>Bug fix</td><td>TDD</td><td>Regression test first</td></tr><tr><td>Legacy migration</td><td>DDD</td><td>Characterize before changing</td></tr></tbody></table><hr><h2 id="_5-phase-structure" tabindex="-1">5-Phase Structure <a class="header-anchor" href="#_5-phase-structure" aria-label="Permalink to &quot;5-Phase Structure&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│                  POC-First Workflow                          │</span></span>
<span class="line"><span>│                                                             │</span></span>
<span class="line"><span>│  Phase 1        Phase 2        Phase 3        Phase 4       │</span></span>
<span class="line"><span>│  ┌──────────┐   ┌──────────┐   ┌──────────┐   ┌─────────┐  │</span></span>
<span class="line"><span>│  │ Make It  │──▶│ Refactor │──▶│ Testing  │──▶│ Quality │  │</span></span>
<span class="line"><span>│  │  Work    │   │          │   │          │   │  Gates  │  │</span></span>
<span class="line"><span>│  │ (50-60%) │   │ (15-20%) │   │ (15-20%) │   │(10-15%) │  │</span></span>
<span class="line"><span>│  └──────────┘   └──────────┘   └──────────┘   └─────────┘  │</span></span>
<span class="line"><span>│       │                                            │        │</span></span>
<span class="line"><span>│       │              Phase 5                       │        │</span></span>
<span class="line"><span>│       │         ┌──────────────┐                   │        │</span></span>
<span class="line"><span>│       └────────▶│ PR Lifecycle │◀──────────────────┘        │</span></span>
<span class="line"><span>│                 └──────────────┘                            │</span></span>
<span class="line"><span>└─────────────────────────────────────────────────────────────┘</span></span></code></pre></div><h3 id="phase-1-make-it-work-50-60-of-effort" tabindex="-1">Phase 1: Make It Work (50-60% of effort) <a class="header-anchor" href="#phase-1-make-it-work-50-60-of-effort" aria-label="Permalink to &quot;Phase 1: Make It Work (50-60% of effort)&quot;">​</a></h3><p><strong>Goal</strong>: Get the core functionality working end-to-end.</p><ul><li>Focus ONLY on making it work</li><li>Hardcoding is acceptable</li><li>Skip edge cases and error handling</li><li>No premature optimization</li><li>Use console.log freely for debugging</li></ul><p><strong>Done when</strong>: The feature works for the happy path. Demo-able to stakeholders.</p><h3 id="phase-2-refactor-15-20-of-effort" tabindex="-1">Phase 2: Refactor (15-20% of effort) <a class="header-anchor" href="#phase-2-refactor-15-20-of-effort" aria-label="Permalink to &quot;Phase 2: Refactor (15-20% of effort)&quot;">​</a></h3><p><strong>Goal</strong>: Clean up code without changing behavior.</p><ul><li>Extract hardcoded values to constants/config</li><li>Split large files (&gt;400 lines)</li><li>Apply naming conventions</li><li>Remove debug statements</li><li>Add proper types</li></ul><p><strong>Done when</strong>: Code is clean, well-organized, and still works.</p><h3 id="phase-3-testing-15-20-of-effort" tabindex="-1">Phase 3: Testing (15-20% of effort) <a class="header-anchor" href="#phase-3-testing-15-20-of-effort" aria-label="Permalink to &quot;Phase 3: Testing (15-20% of effort)&quot;">​</a></h3><p><strong>Goal</strong>: Add comprehensive test coverage.</p><ul><li>Unit tests for business logic (80%+ coverage)</li><li>Integration tests for API endpoints</li><li>E2E tests for critical user flows</li><li>Edge case and error scenario coverage</li></ul><p><strong>Done when</strong>: Test suite passes, coverage meets threshold (80%+).</p><h3 id="phase-4-quality-gates-10-15-of-effort" tabindex="-1">Phase 4: Quality Gates (10-15% of effort) <a class="header-anchor" href="#phase-4-quality-gates-10-15-of-effort" aria-label="Permalink to &quot;Phase 4: Quality Gates (10-15% of effort)&quot;">​</a></h3><p><strong>Goal</strong>: Production-ready quality.</p><ul><li>Zero linting errors and type errors</li><li>Security audit clean</li><li>Performance acceptable</li><li>Documentation complete</li></ul><p><strong>Quality Gate Checklist</strong>:</p><ul><li>[ ] Build passes with zero errors</li><li>[ ] All tests passing, coverage &gt;= 80%</li><li>[ ] Lint clean (zero errors/warnings)</li><li>[ ] Type check clean</li><li>[ ] No critical/high security vulnerabilities</li><li>[ ] Key functions documented</li></ul><h3 id="phase-5-pr-lifecycle" tabindex="-1">Phase 5: PR Lifecycle <a class="header-anchor" href="#phase-5-pr-lifecycle" aria-label="Permalink to &quot;Phase 5: PR Lifecycle&quot;">​</a></h3><p><strong>Goal</strong>: Create PR and get it merged.</p><p>Uses the <a href="./pr-lifecycle.html">PR Lifecycle Automation</a> workflow for automated PR management.</p><hr><h2 id="intent-classification" tabindex="-1">Intent Classification <a class="header-anchor" href="#intent-classification" aria-label="Permalink to &quot;Intent Classification&quot;">​</a></h2><p>Before starting, the workflow automatically classifies your intent:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Is this NEW code (no existing behavior)?</span></span>
<span class="line"><span>  ├── YES → POC-First Workflow</span></span>
<span class="line"><span>  └── NO  → Is existing code being modified?</span></span>
<span class="line"><span>        ├── YES → DDD Workflow (ANALYZE-PRESERVE-IMPROVE)</span></span>
<span class="line"><span>        └── Regression test needed? → TDD Workflow (RED-GREEN-REFACTOR)</span></span></code></pre></div><hr><h2 id="phase-transition-rules" tabindex="-1">Phase Transition Rules <a class="header-anchor" href="#phase-transition-rules" aria-label="Permalink to &quot;Phase Transition Rules&quot;">​</a></h2><ol><li><strong>No skipping phases</strong>: Phase 1 → 2 → 3 → 4 → 5 (strict order)</li><li><strong>Phase gate required</strong>: Each phase ends with a [VERIFY] checkpoint</li><li><strong>No regression</strong>: Previous phase&#39;s verification must still pass</li><li><strong>User confirmation</strong>: Phase 1 completion requires user confirmation</li></ol><hr><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage&quot;">​</a></h2><h3 id="slash-command" tabindex="-1">Slash Command <a class="header-anchor" href="#slash-command" aria-label="Permalink to &quot;Slash Command&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Full POC workflow</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/kroot:poc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;User authentication with JWT&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Start from specific phase</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/kroot:poc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Auth system&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --phase</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Skip PR phase</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/kroot:poc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Auth system&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --skip-pr</span></span></code></pre></div><h3 id="as-a-skill" tabindex="-1">As a Skill <a class="header-anchor" href="#as-a-skill" aria-label="Permalink to &quot;As a Skill&quot;">​</a></h3><p>The workflow is also available as a skill for use by other commands and agents:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Skill(&quot;kroot-workflow-poc&quot;)</span></span></code></pre></div><hr><h2 id="task-format-integration" tabindex="-1">Task Format Integration <a class="header-anchor" href="#task-format-integration" aria-label="Permalink to &quot;Task Format Integration&quot;">​</a></h2><p>All tasks within the POC workflow use the <a href="./task-format.html">Structured Task Format</a> with Do/Files/Done when/Verify/Commit fields and [VERIFY] quality checkpoints.</p><hr><h2 id="comparison-with-other-workflows" tabindex="-1">Comparison with Other Workflows <a class="header-anchor" href="#comparison-with-other-workflows" aria-label="Permalink to &quot;Comparison with Other Workflows&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Aspect</th><th>POC-First</th><th>TDD</th><th>DDD</th></tr></thead><tbody><tr><td><strong>Starting point</strong></td><td>Working code</td><td>Failing test</td><td>Existing behavior analysis</td></tr><tr><td><strong>Test timing</strong></td><td>Phase 3 (after working)</td><td>Before implementation</td><td>Before modification</td></tr><tr><td><strong>Best for</strong></td><td>Greenfield features</td><td>New functions with clear specs</td><td>Refactoring existing code</td></tr><tr><td><strong>Risk</strong></td><td>Technical debt (mitigated by phases)</td><td>Over-testing</td><td>Over-analysis</td></tr><tr><td><strong>Speed to demo</strong></td><td>Fastest</td><td>Moderate</td><td>Slowest</td></tr></tbody></table><hr><h2 id="related-documentation" tabindex="-1">Related Documentation <a class="header-anchor" href="#related-documentation" aria-label="Permalink to &quot;Related Documentation&quot;">​</a></h2><ul><li><a href="./task-format.html">Structured Task Format</a> — Task decomposition structure</li><li><a href="./pr-lifecycle.html">PR Lifecycle Automation</a> — Phase 5 automation</li><li><a href="./tdd-ddd.html">TDD &amp; DDD Workflow</a> — Alternative development methodologies</li><li><a href="./ralph-loop.html">Ralph Loop</a> — Iterative improvement within phases</li></ul>`,52)])])}const u=t(n,[["render",o]]);export{f as __pageData,u as default};
